CREATE TABLE finance_balance_snapshot (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,account_id UUID NOT NULL,owner_id UUID NOT NULL,snapshot_date DATE NOT NULL,balance NUMERIC(19,4) NOT NULL,currency CHAR(3) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),FOREIGN KEY(account_id) REFERENCES finance_account(id),UNIQUE(account_id,snapshot_date)); CREATE INDEX idx_finance_balance_snapshot ON finance_balance_snapshot(ledger_id,snapshot_date DESC);
